script:
card({ name: "Live poll", icon: 'poll' });
const words = {
  ask: "What should we ask?",
  noQuestion: "Ask a question, then add options",
  add: "Add an option",
  empty: "No options yet",
  votes: "{p0} votes",
  leading: "{p0} is ahead",
  tie: "It's a tie",
  clear: "Clear votes",
  full: "Eight options at most",
  twice: "{p0} is already an option",
  onlySender: "Only the person who sent the card can do that",
};

// Anyone adds options. Everyone has one vote: tap another to move it, or
// the same one to take it back. Only the sender can clear the votes.
function init() {
  return { question: '', options: [], votes: {} };
}

on.ask = (s, args) => {
  s.question = String(args.value || '').trim().slice(0, 120);
};

on.add = (s, args) => {
  const option = String(args.value || '').trim().slice(0, 60);
  if (!option) return;
  if (s.options.length >= 8) throw words.full;
  if (s.options.some(o => o.toLowerCase() === option.toLowerCase())) throw words.twice.replace('{p0}', option);
  s.options.push(option);
};

on.vote = (s, args, ctx) => {
  if (s.votes[ctx.author] === args.index) delete s.votes[ctx.author];
  else s.votes[ctx.author] = args.index;
};

on.clear = (s, args, ctx) => {
  if (ctx.author !== ctx.sender) throw words.onlySender;
  s.votes = {};
};

function view(s, me) {
  const counts = s.options.map((o, i) => Object.values(s.votes).filter(v => v === i).length);
  const total = Object.keys(s.votes).length;
  const top = counts.reduce((m, n) => Math.max(m, n), 0);
  const leaders = s.options.filter((o, i) => top > 0 && counts[i] === top);
  const mine = s.votes[me.id] ?? null;
  return column([
    s.question ? text(s.question, { size: 'large', bold: true }) : input('question', words.ask, 'ask'),
    s.options.length
      ? choice('vote', s.options, 'vote', { selected: mine === null ? [] : mine, counts })
      : text(s.question ? words.empty : words.noQuestion, { tone: 'muted' }),
    total > 0 && row([
      badge(words.votes.replace('{p0}', total)),
      badge(leaders.length === 1 ? words.leading.replace('{p0}', leaders[0]) : words.tie, { tone: 'accent' }),
    ]),
    input('option', words.add, 'add'),
    me.isSender && total > 0 && button(words.clear, 'clear', null, { tone: 'muted', align: 'end' }),
  ]);
}
